const bizRS=p.renderSettings,bizBS=p.bindSettings,bizRC=p.renderCalculator,bizBC=p.bindCalculator,bizRP=p.renderPrinters,bizBP=p.bindPrinters,bizBase=p.baseStyle,bizRO=p.renderOrders,bizBO=p.bindOrders;
function bizInit(){if(!Array.isArray(this.data.customers))this.data.customers=[];if(!Array.isArray(this.data.customerHistory))this.data.customerHistory=[];const c=this.data.calculator||(this.data.calculator={});if(c.customerId===undefined)c.customerId='';if(c.customerName===undefined)c.customerName='';const x=this.data.printers?.find(v=>/x1\s*carbon|x1c/i.test(String(v.name||'')));if(x&&(!Number.isFinite(Number(x.electricity))||Number(x.electricity)<=0))x.electricity=.15;}
p.renderCalculator=function(r){bizInit.call(this);let h=bizRC.call(this,r),c=this.data.calculator,opts=this.data.customers.map(x=>`<option value="${this.escape(x.id)}">${this.escape(x.name)}</option>`).join('');const card=`<div class="business-customer-card"><h3>👤 Клиент</h3><div class="business-customer-row"><select id="biz-customer"><option value="">Без сохранённого клиента</option>${opts}</select><button type="button" id="biz-new-customer">＋ Новый</button></div><input id="biz-name" placeholder="Имя / название клиента" value="${this.escape(c.customerName||'')}"><input id="biz-phone" placeholder="Телефон / контакт (необязательно)"><div class="business-customer-hint">Клиент сохраняется в расчёте, истории и PDF.</div></div>`;return h.replace('<div class="calculator-presets">',card+'<div class="calculator-presets">');};
p.bindCalculator=function(){bizBC.call(this);bizInit.call(this);const s=this.querySelector('#biz-customer'),n=this.querySelector('#biz-name'),ph=this.querySelector('#biz-phone'),cur=this.data.customers.find(x=>x.id===this.data.calculator.customerId);if(s)s.value=this.data.calculator.customerId||'';if(n)n.value=this.data.calculator.customerName||cur?.name||'';if(ph)ph.value=cur?.phone||'';if(s)s.addEventListener('change',()=>{const c=this.data.customers.find(x=>x.id===s.value);this.data.calculator.customerId=c?.id||'';this.data.calculator.customerName=c?.name||'';if(n)n.value=c?.name||'';if(ph)ph.value=c?.phone||'';this.saveData();});if(n)n.addEventListener('input',()=>{this.data.calculator.customerName=n.value;this.data.calculator.customerId='';this.saveData();});const add=this.querySelector('#biz-new-customer');if(add)add.onclick=()=>{const name=(n?.value||'').trim(),phone=(ph?.value||'').trim();if(!name){this.toast('Введите имя клиента');return;}let c=this.data.customers.find(x=>x.name.toLowerCase()===name.toLowerCase());if(!c){c={id:this.id('customer'),name,phone,createdAt:new Date().toISOString()};this.data.customers.unshift(c);}else if(phone)c.phone=phone;this.data.calculator.customerId=c.id;this.data.calculator.customerName=c.name;this.saveData();this.render();this.toast('✓ Клиент сохранён');};const save=this.querySelector('#save-calc');if(save)save.addEventListener('click',()=>setTimeout(()=>{const r=this.calculate(),c=this.data.calculator;this.data.customerHistory.unshift({id:this.id('history'),createdAt:new Date().toISOString(),customerId:c.customerId||'guest',customerName:c.customerName||this.customerName(c.customerType)||'Без клиента',material:r.material?.name||'—',printer:r.printer?.name||'—',quantity:r.q||1,total:Number(r.salePrice)||0,cost:Number(r.cost)||0,profit:Math.max(0,(Number(r.salePrice)||0)-(Number(r.cost)||0))});this.data.customerHistory=this.data.customerHistory.slice(0,500);this.saveData();},50));};
p.renderOrders=function(){bizInit.call(this);let h=bizRO.call(this);const rows=this.data.customers.map(c=>`<div class="customer-row"><div><b>${this.escape(c.name)}</b>${c.phone?`<div class="customer-meta">${this.escape(c.phone)}</div>`:''}<div class="customer-meta">Расчётов: ${this.data.customerHistory.filter(x=>x.customerId===c.id).length}</div></div><button type="button" data-biz-del="${this.escape(c.id)}">Удалить</button></div>`).join('')||'<div class="customer-empty">Пока нет сохранённых клиентов.</div>';const hist=this.data.customerHistory.slice(0,20).map(x=>`<tr><td>${new Date(x.createdAt).toLocaleDateString('ru-RU')}</td><td>${this.escape(x.customerName)}</td><td>${this.escape(x.material)}</td><td>${x.quantity}</td><td>${this.money(x.total)}</td><td>${this.money(x.profit)}</td></tr>`).join('')||'<tr><td colspan="6">История пока пуста.</td></tr>';const block=`<div class="business-customers"><h3>👥 Клиенты</h3><div class="business-section-hint">Здесь находится база клиентов и их последние сохранённые расчёты.</div><div class="customer-list">${rows}</div><h4>История клиентов</h4><div class="history-table-wrap"><table><thead><tr><th>Дата</th><th>Клиент</th><th>Материал</th><th>Кол-во</th><th>Цена</th><th>Прибыль</th></tr></thead><tbody>${hist}</tbody></table></div></div>`;return block+h;};
