const pdfBusinessBind=p.bindCalculator;
function buildBusinessPdfHtml(r,c,s,host){
  const name=(c.customerName||'Без клиента').trim();
  const date=new Date().toLocaleString('ru-RU');
  const clientType=host.customerName(c.customerType);
  const discount=c.customerType==='regular'?Number(s.commercial?.regularDiscount)||0:Number(r.discount)||0;
  const waste=Number(s.waste)||0;
  const tariff=Math.max(0,Number(s.electricityPrice)||10.25);
  const printerConsumption=Math.max(0,Number(r.printer?.electricity)||0);
  const electricity=printerConsumption*tariff;
  const printerHourly=electricity+Number(r.printer?.depreciation||0)+Number(r.printer?.consumables||0);
  const esc=v=>host.escape(v);
  const money=v=>host.money(v);
  const row=(a,b,cls='')=>`<tr class="${cls}"><td>${esc(a)}</td><td>${esc(String(b))}</td></tr>`;
  return `<!doctype html><html><head><meta charset="utf-8"><title>Расчёт 3D-печати</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:#171717;font-size:11px;line-height:1.4;margin:0}.sheet{max-width:760px;margin:auto}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid #222;padding-bottom:10px;margin-bottom:16px}.title{font-size:21px;font-weight:700}.sub{font-size:10px;color:#666;margin-top:3px}.total{text-align:right;white-space:nowrap}.total .label{font-size:9px;color:#666;text-transform:uppercase}.total .value{font-size:24px;font-weight:800;margin-top:2px}.client{border:1px solid #ddd;border-radius:8px;padding:9px 11px;margin-bottom:14px}.client-name{font-size:14px;font-weight:700}.client-type{font-size:10px;color:#666;margin-top:3px}.sec{margin:13px 0}.sec h2{font-size:12px;margin:0 0 6px;padding-bottom:4px;border-bottom:1px solid #ddd}.tbl{width:100%;border-collapse:collapse;font-size:10.5px}.tbl td{padding:5px 4px;border-bottom:1px solid #eee}.tbl td:last-child{text-align:right;font-weight:600}.tbl .important td{font-weight:700;border-top:1px solid #bbb}.sum{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin-top:10px}.box{border:1px solid #ddd;border-radius:7px;padding:8px}.box .label{font-size:8px;color:#666}.box .value{font-size:13px;font-weight:700;margin-top:2px}.formula{padding:10px;border:1px solid #ddd;border-radius:7px;font-size:9.5px;line-height:1.5;background:#fafafa}.formula b{font-weight:700}.foot{margin-top:16px;padding-top:7px;border-top:1px solid #ddd;font-size:8px;color:#777;text-align:center}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="sheet"><div class="head"><div><div class="title">Расчёт 3D-печати</div><div class="sub">Сформирован: ${esc(date)}</div></div><div class="total"><div class="label">Итого за заказ</div><div class="value">${money(r.salePrice)}</div></div></div><div class="client"><div class="client-name">${esc(name)}</div><div class="client-type">${esc(clientType)}${discount?` · скидка −${discount}%`:''}</div></div><div class="sec"><h2>Параметры заказа</h2><table class="tbl">${row('Материал',r.material?.name||'—')}${row('Принтер',r.printer?.name||'—')}${row('Количество',`${r.q} шт.`)}${row('Вес одного изделия',`${Number(r.weight||0).toFixed(1)} г`)}${row('Отходы',`${waste}%`)}${row('Вес с учётом отходов',`${Number(r.totalEffectiveWeight||0).toFixed(1)} г`)}${row('Время печати',`${Math.floor(r.totalHours)} ч ${Math.round((r.totalHours%1)*60)} мин`)}</table></div><div class="sec"><h2>Себестоимость</h2><table class="tbl">${row('Материал',money(r.materialCost))}${row('Отходы',`${waste}%`)}${row('Печать',money(r.machineCost))}${row(`Электроэнергия принтера · ${printerConsumption.toFixed(2)} кВт·ч/ч × ${tariff.toFixed(2)} ₽/кВт·ч`,money(electricity))}${row('Амортизация + расходники',money(Number(r.machineCost||0)-Number(electricity*r.totalHours*r.q||0)))}${row(`Упаковка · ${r.packagingRate||0} ₽/шт. × ${r.packagingQty||0} шт.`,money(r.packagingCost))}${row(`Постобработка · ${r.postProcessingRate||0} ₽/шт. × ${r.postProcessingQty||0} шт.`,money(r.postProcessingCost))}${row('Итого себестоимость',money(r.cost),'important')}</table><div class="formula" style="margin-top:8px"><b>Стоимость часа принтера:</b> ${printerConsumption.toFixed(2)} кВт·ч/ч × ${tariff.toFixed(2)} ₽/кВт·ч = ${electricity.toFixed(2)} ₽/ч; + амортизация ${Number(r.printer?.depreciation||0).toFixed(2)} ₽/ч; + расходники ${Number(r.printer?.consumables||0).toFixed(2)} ₽/ч → <b>${printerHourly.toFixed(2)} ₽/ч</b>.</div></div><div class="sum"><div class="box"><div class="label">ЦЕНА / ШТ.</div><div class="value">${money(r.salePricePerUnit)}</div></div><div class="box"><div class="label">МАРЖА</div><div class="value">${Number(r.margin||0).toFixed(1)}%</div></div></div><div class="sec"><h2>Коммерческие условия</h2><table class="tbl">${row('Цена с базовой наценкой',money(r.retailBasePrice))}${row(discount?`Скидка · −${discount}%`:'Скидка','0 ₽'===money(r.discountAmount)?'0 ₽':`−${money(r.discountAmount)}`)}${row('Срочность',r.urgentMarkup?`+${r.urgentMarkup}% · ${money(r.urgentCost)}`:'Нет')}${row('Минимальный заказ',money(r.minimumOrder))}${row('Округление',`до ${money(s.rounding)}`)}${row('Итого за заказ',money(r.salePrice),'important')}</table></div><div class="sec"><h2>Как сформирована цена</h2><div class="formula"><b>Материал:</b> вес изделия × (1 + отходы) × количество × цена материала/г.<br><b>Печать:</b> время × [электроэнергия + амортизация + расходники] × количество.<br><b>Дополнительно:</b> упаковка и постобработка по указанному количеству.<br><b>Цена:</b> себестоимость + наценка → скидка клиента → срочность → минимальный заказ → округление.</div></div><div class="foot">Расчёт сформирован в 3D Print Calculator</div></div><script>window.onload=()=>setTimeout(()=>{window.focus();window.print()},250);</script></body></html>`;
}
pdfBusinessBind=function(){pdfBusinessBind.call(this);const b=this.querySelector('#print-calc');if(b){b.textContent='🖨 Печать PDF';b.onclick=()=>{const r=this.calculate(),c=this.data.calculator,s=this.data.settings||{};const w=window.open('','_blank','width=900,height=1000');if(!w){this.toast('⚠️ Разрешите всплывающие окна для печати');return;}w.document.open();w.document.write(buildBusinessPdfHtml(r,c,s,this));w.document.close();};}};
p.bindCalculator=pdfBusinessBind;
const pdfBase=p.baseStyle;
p.baseStyle=function(){const b=pdfBase.call(this),x=`.business-pdf{display:none}`;return b.replace('</style>',x+'</style>');};
